package org.sigf.ui;
import org.sigf.app.*; import org.sigf.config.*; import org.sigf.security.*; import org.sigf.services.*; import org.sigf.ui.*; import org.sigf.domain.*;

import javafx.application.Platform; import javafx.concurrent.Task; import javafx.geometry.Insets; import javafx.scene.*; import javafx.scene.control.*; import javafx.scene.control.cell.PropertyValueFactory; import javafx.scene.layout.*; import javafx.stage.Stage; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import java.util.concurrent.Callable;
public final class Workspace {
 private final Stage stage; private final Database db; private final Security.User user; private final InventoryService service; private final TableView<InventoryService.Product> table=new TableView<>(); private final TextField search=new TextField(); private final Label status=new Label(); private final BorderPane root=new BorderPane(); private final java.util.List<OperationalPane> panes=new java.util.ArrayList<>(); private final Label pharmacyName=new Label("SIGF  /  FARMACIA"); private final javafx.scene.image.ImageView pharmacyLogo=new javafx.scene.image.ImageView();
 public Workspace(Stage s,Database d,Security.User u){stage=s;db=d;user=u;service=new InventoryService(d);}
 public void show(){Label brand=pharmacyName;brand.getStyleClass().add("brand");pharmacyLogo.setFitWidth(40);pharmacyLogo.setFitHeight(40);pharmacyLogo.setPreserveRatio(true);Region space=new Region();HBox.setHgrow(space,Priority.ALWAYS);MenuItem logout=new MenuItem("Cerrar sesión");logout.setOnAction(e->{try{var l=new javafx.fxml.FXMLLoader(Main.class.getResource("/fxml/login.fxml"));Parent view=l.load();((LoginController)l.getController()).init(stage,db);stage.getScene().setRoot(view);}catch(Exception ex){error(ex);}});MenuButton account=new MenuButton(user.name()+" · "+(user.role().equals("ADMIN")?"Administrador":"Cajero"),UiIcons.icon("Contactos","account-icon"),logout);account.getStyleClass().add("account-menu");HBox bar=new HBox(18,pharmacyLogo,brand,space,account);bar.setAlignment(javafx.geometry.Pos.CENTER_LEFT);bar.getStyleClass().add("topbar");root.setTop(bar);
 Label title=new Label("Productos e inventario");title.getStyleClass().add("heading");Label sub=new Label("Consulta existencias, recibe lotes y registra ventas.");sub.getStyleClass().add("muted");search.setPromptText("Buscar por nombre, código o código de barras");search.setPrefWidth(350);search.setOnAction(e->refresh());Button find=new Button("Buscar");find.setOnAction(e->refresh());HBox filters=new HBox(10,search,find);column("Código","code",140);column("Producto","name",300);column("Precio sin IVA","price",130);column("Existencia total","stock",150);column("Activo","active",90);table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_ALL_COLUMNS);table.setPlaceholder(new Label("No hay productos para mostrar."));VBox.setVgrow(table,Priority.ALWAYS);
 Button add=new Button("Nuevo producto"),edit=new Button("Editar"),receive=new Button("Recibir lote");add.getStyleClass().add("primary");add.setOnAction(e->productForm(null));edit.setOnAction(e->{var p=selected();if(p!=null)productForm(p);});receive.setOnAction(e->receive());if(!user.role().equals("ADMIN")){add.setDisable(true);edit.setDisable(true);receive.setDisable(true);}HBox actions=new HBox(10,add,edit,receive);VBox content=new VBox(16,title,sub,filters,table,actions,status);content.getStyleClass().add("workspace");TabPane navigation=new TabPane();navigation.getStyleClass().add("main-navigation"); navigation.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);
 java.util.Map<String,Tab> childTabs=new java.util.LinkedHashMap<>();java.util.Map<String,Tab> groups=new java.util.LinkedHashMap<>();
 Tab home=new Tab("Inicio");home.setGraphic(UiIcons.icon("Inicio","nav-icon"));navigation.getTabs().add(home);groups.put("Inicio",home);
 java.util.function.Consumer<String> navigate=target->{Tab child=childTabs.get(target);if(child!=null){for(Tab group:navigation.getTabs())if(group.getContent() instanceof TabPane nested && nested.getTabs().contains(child)){navigation.getSelectionModel().select(group);nested.getSelectionModel().select(child);return;}}};
 home.setContent(new DashboardPane(db,navigate));
 String[][] modules={{"Ventas","Punto de venta","cart"},{"Ventas","Historial de ventas","sales"},{"Ventas","Ventas pendientes","pending"},{"Inventario","Productos","products"},{"Inventario","Lotes","batches"},{"Compras","Compras","purchases"},{"Compras","Compras pendientes","purchase_pending"},{"Contactos","Clientes","customers"},{"Contactos","Proveedores","suppliers"},{"Reportes","Reportes","reports"},{"Administración","Usuarios","users"},{"Administración","Configuración","settings"}};
 for(String[] m:modules){if((m[2].equals("users")||m[2].equals("settings")||m[2].equals("purchase_pending"))&&!user.role().equals("ADMIN"))continue;
 Tab group=groups.get(m[0]);if(group==null){group=new Tab(m[0]);group.setGraphic(UiIcons.icon(m[0],"nav-icon"));TabPane nested=new TabPane();nested.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);nested.getStyleClass().add("section-tabs");group.setContent(nested);groups.put(m[0],group);navigation.getTabs().add(group);}
 Tab tab=new Tab(m[1]);childTabs.put(m[1],tab);
 if(m[2].equals("products")){tab.setContent(content);tab.setOnSelectionChanged(e->{if(tab.isSelected())refresh();});}else tab.setOnSelectionChanged(e->{if(tab.isSelected()&&tab.getContent()==null){OperationalPane pane=new OperationalPane(db,user,m[2],m[1],this::refreshIdentity,(kind,id)->panes.forEach(existing->existing.resolvedElsewhere(kind,id)));panes.add(pane);tab.setContent(pane);}else if(tab.isSelected()&&tab.getContent() instanceof OperationalPane pane)pane.reload();});
 ((TabPane)group.getContent()).getTabs().add(tab);
 }
navigation.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{if(b==home)((DashboardPane)home.getContent()).reload();else if(b!=null&&b.getContent() instanceof TabPane nested){var t=nested.getSelectionModel().getSelectedItem();if(t!=null&&t.getContent() instanceof OperationalPane pane)pane.reload();else if(t!=null&&t.getText().equals("Productos"))refresh();}});
root.setCenter(navigation);stage.getScene().setRoot(root);navigation.getSelectionModel().select(0);refreshIdentity();refresh(); }
 private void refreshIdentity(){Task<java.util.Optional<PharmacyProfileService.Profile>> task=new Task<>(){protected java.util.Optional<PharmacyProfileService.Profile> call()throws Exception{return new PharmacyProfileService(db).load();}};task.setOnSucceeded(e->task.getValue().ifPresent(profile->{pharmacyName.setText("SIGF  /  "+profile.name());byte[] bytes=profile.logo();pharmacyLogo.setImage(bytes==null?null:new javafx.scene.image.Image(new java.io.ByteArrayInputStream(bytes),40,40,true,true));}));Thread t=new Thread(task,"sigf-identity");t.setDaemon(true);t.start();}
 private void column(String title,String prop,double width){TableColumn<InventoryService.Product,Object> c=new TableColumn<>(title);c.setCellValueFactory(x->new javafx.beans.property.ReadOnlyObjectWrapper<>(switch(prop){case "code"->x.getValue().code();case "name"->x.getValue().name();case "price"->x.getValue().price();case "stock"->x.getValue().stock();default->x.getValue().active();}));c.setPrefWidth(width);table.getColumns().add(c);}
 private <T> void run(String label,Callable<T> work,java.util.function.Consumer<T> success){status.setText(label);root.setDisable(true);Task<T> task=new Task<>(){protected T call()throws Exception{return work.call();}};task.setOnSucceeded(e->{root.setDisable(false);status.setText("Listo");success.accept(task.getValue());});task.setOnFailed(e->{root.setDisable(false);status.setText("No se completó la operación");error(task.getException());});Thread t=new Thread(task);t.setDaemon(true);t.start();}
 private void refresh(){String q=search.getText();run("Consultando…",()->service.products(q),v->table.getItems().setAll(v));}
 private InventoryService.Product selected(){var p=table.getSelectionModel().getSelectedItem();if(p==null)error(new IllegalArgumentException("Seleccione un producto"));return p;}
 private Optional<List<String>> form(String title,String[] labels,String[] values){return FormControls.show(title,labels,values,Set.of());}
 private record ProductFormData(InventoryService.ProductDetails details,Map<String,List<String>> catalog) {}
 private void productForm(InventoryService.Product p){run("Cargando catálogo…",()->new ProductFormData(p==null?null:service.details(p.id()),service.catalog()),data->showProductForm(p==null?null:p.id(),data.details(),data.catalog()));}
 private void showProductForm(Long id,InventoryService.ProductDetails d,Map<String,List<String>> catalog){String[] labels={"Código","Código de barras","Nombre","Categoría","Descripción","Presentación","Laboratorio","Costo","Precio sin IVA","Existencia mínima","Activo true/false","Tasa IVA (0 exento; 0.15 gravado)"};String[] values=d==null?new String[]{"","","","","","","","0.00","0.00","0","true",""}:new String[]{d.code(),d.barcode(),d.name(),d.category(),d.description(),d.presentation(),d.laboratory(),d.cost().toPlainString(),d.price().toPlainString(),Integer.toString(d.minimum()),Boolean.toString(d.active()),d.taxRate()==null?"":d.taxRate().toPlainString()};FormControls.save("Datos del producto",labels,values,Set.of(),catalog,v->{var data=new InventoryService.ProductDetails(v.get(0),v.get(1),v.get(2),v.get(3),v.get(4),v.get(5),v.get(6),new BigDecimal(v.get(7)),new BigDecimal(v.get(8)),Integer.parseInt(v.get(9)),Boolean.parseBoolean(v.get(10)),new BigDecimal(v.get(11)));service.saveDetails(user,id,data);}).ifPresent(v->refresh());}
 private void receive(){var p=selected();if(p==null)return;run("Consultando proveedores…",()->new Operations(db).grid("suppliers"),grid->{java.util.LinkedHashMap<String,Long> choices=new java.util.LinkedHashMap<>();choices.put("Sin proveedor",null);for(var row:grid.rows())if(Boolean.parseBoolean(row.get(3)))choices.put(row.get(0)+" · "+row.get(1),Long.valueOf(row.get(0)));ChoiceDialog<String> pick=new ChoiceDialog<>("Sin proveedor",choices.keySet());pick.setTitle("Proveedor");pick.setHeaderText("Seleccione proveedor");pick.showAndWait().ifPresent(label->receiveFromSupplier(p,choices.get(label)));});}
 private void receiveFromSupplier(InventoryService.Product p,Long supplier){UUID key=UUID.randomUUID();FormControls.save("Recibir lote · "+p.name(),new String[]{"Lote","Vence (AAAA-MM-DD)","Cantidad","Costo unitario"},new String[]{"","","1","0.00"},Set.of(),Map.of(),v->{var item=new PurchaseItem(p.id(),v.get(0).trim(),LocalDate.parse(v.get(1)),Integer.parseInt(v.get(2)),new BigDecimal(v.get(3)));var request=new PurchaseRecovery.Pending(key,supplier,List.of(item));var recovery=new PurchaseRecovery(db);recovery.save(user,request);recovery.resolve(user,key);recovery.acknowledge(user,key,false);}).ifPresent(v->refresh());}
 private void info(String m){new Alert(Alert.AlertType.INFORMATION,m,ButtonType.OK).showAndWait();}private void error(Throwable e){new Alert(Alert.AlertType.ERROR,e.getMessage()==null?"Error inesperado":e.getMessage(),ButtonType.OK).showAndWait();}
}